import math

cable = [0.9, 0.8, 0.1]
wire = [0.8, 0.9, 0.2]
mango = [0.1, 0.0, 0.9]

def dot(a, b):
    return sum(x * y for x, y in zip(a, b))

def cosine(a, b):
    return dot(a, b) / (math.sqrt(dot(a, a)) * math.sqrt(dot(b, b)))

print(f"dot cable-wire: {dot(cable, wire):.2f}")
print(f"cos cable-wire: {cosine(cable, wire):.2f}")
print(f"dot cable-mango: {dot(cable, mango):.2f}")
print(f"cos cable-mango: {cosine(cable, mango):.2f}")
